		compSize := len(component)
		for i := compSize - 1; i >= 0; i-- {
			u, size := component[i], 1
			for _, v32 := range graph[u] {
				if v := int(v32); !removed[v] && scratchParent[v] == u {
					size += subSize[v]
				}
			}
			subSize[u] = size
		}
		center := seed
		for _, u := range component {
			largest := compSize - subSize[u]
			for _, v32 := range graph[u] {
				if v := int(v32); !removed[v] && scratchParent[v] == u && subSize[v] > largest {
					largest = subSize[v]
				}
			}
			if largest <= compSize/2 {
				center = u
				break
			}
		}

		removed[center] = true
		addChain(center, center, 0, -1)
		allFreq = append(allFreq[:0], 1)
		for _, nb32 := range graph[center] {
			neighbor := int(nb32)
			if removed[neighbor] {
				continue
			}
			pending = append(pending, neighbor)
			bid := len(branchOff)
			branchDist = branchDist[:0]
			mx := 0
			walk3 = append(walk3[:0], [3]int{neighbor, center, 1})
			for len(walk3) > 0 {
				w := walk3[len(walk3)-1]
				walk3 = walk3[:len(walk3)-1]
				u, p, d := w[0], w[1], w[2]
				addChain(u, center, d, bid)
				branchDist = append(branchDist, d)
				mx = max(mx, d)
				for len(allFreq) <= d {
					allFreq = append(allFreq, 0)
				}
				allFreq[d]++
				for _, v32 := range graph[u] {
					if v := int(v32); v != p && !removed[v] {
						walk3 = append(walk3, [3]int{v, u, d + 1})
					}
				}
			}
			localFreq = append(localFreq[:0], make([]int, mx+1)...)
			for _, d := range branchDist {
				localFreq[d]++
			}
			branchOff = append(branchOff, len(pool))
			branchLen = append(branchLen, mx+1)
			sub := 0
			for _, f := range localFreq {
				sub += f
				pool = append(pool, int32(sub)) // prefix counts by distance
			}
		}
		wholeOff[center] = len(pool)
		wholeLen[center] = len(allFreq)
		sub := 0
		for _, f := range allFreq {
			sub += f
			pool = append(pool, int32(sub))
		}
	}
	// Number of vertices within `radius` of vertex in the whole tree.
	ballSize := func(vertex, radius int) int {
		answer, base := 0, vertex*LOG
		for i := 0; i < chainLen[vertex]; i++ {
			remaining := radius - int(chainD[base+i])
			if remaining < 0 {
				continue
			}
			c, b := int(chainC[base+i]), int(chainB[base+i])
			answer += int(pool[wholeOff[c]+min(remaining, wholeLen[c]-1)])
			if b >= 0 {
				answer -= int(pool[branchOff[b]+min(remaining, branchLen[b]-1)])
			}
		}
		return answer
	}

	// Binary search the diameter; a kept subtree has diameter at most required-1.
	lower, upper := 0, required-1
	balls := make([]int, n)
	for lower < upper {
		limit := (lower + upper) / 2
		radius := limit / 2
		enough := false
		for v := 0; v < n && !enough; v++ {
			balls[v] = ballSize(v, radius)
			enough = balls[v] >= required
		}
		if !enough && limit%2 == 1 {
			// Edge-centred: parent side within radius of p plus child side within radius of child.
			for child := 1; child < n && !enough; child++ {
				p := parent[child]
				size := balls[p] - subtreeCount(child, radius-1) + subtreeCount(child, radius)
				enough = size >= required
			}
		}
		if enough {
			upper = limit
		} else {
			lower = limit + 1
		}
	}
	fmt.Println(lower)
}
